mapper.select:
SELECT t.id, t.test_key, t.title, t.description, t.thumbnail_image, t.category, c.display_name AS category_display_name, t.test_type, t.estimated_time, t.status, t.created_by, t.play_count, t.created_at, t.updated_at, COUNT(q.id) AS question_count FROM md_test t LEFT JOIN md_test_question q ON t.id = q.test_id AND q.is_active = 1 LEFT JOIN md_content_category c ON t.category = c.category_name
AND t.created_by = #{createdBy}
GROUP BY t.id ORDER BY t.created_at DESC

mapper.insert:
INSERT INTO md_test (
    test_key, title, description, thumbnail_image,
    category, test_type, estimated_time, status, created_by
) VALUES (
    #{testKey}, #{title}, #{description}, #{thumbnailImage},
    #{category}, #{testType}, #{estimatedTime}, #{status}, #{createdBy}
)

INSERT INTO md_test_question (
    test_id, question_order, question_text, domain, is_reverse, is_active
) VALUES (
    #{testId}, #{questionOrder}, #{questionText}, #{domain}, #{reverse}, #{active}
)

mapper.update:
UPDATE md_test_question SET
    question_text = #{questionText},
    domain        = #{domain},
    is_reverse    = #{reverse}
WHERE id = #{id}

mapper.insert:
INSERT INTO md_test_result_type (
    test_id, result_title, result_content, result_image, min_score, max_score
) VALUES (
    #{testId}, #{resultTitle}, #{resultContent}, #{resultImage}, #{minScore}, #{maxScore}
)
